export function calculerSoldeConges(
  droitAnnuelJours: number,
  congesPrisJours: number,
  congesEnCours: number,
  reportN1Jours: number = 0
): number {
  const solde = droitAnnuelJours + reportN1Jours - congesPrisJours - congesEnCours;
  return Math.round(solde * 10) / 10; // NUMERIC(5,1)
}

export function calculerTauxUtilisationConges(
  congesPrisJours: number,
  droitAnnuelJours: number
): number {
  if (droitAnnuelJours <= 0) return 0;
  const taux = (congesPrisJours / droitAnnuelJours) * 100;
  return Math.round(taux * 100) / 100; // NUMERIC(5,2)
}

export function calculerNombreJoursConge(
  dateDebut: string | Date,
  dateFin: string | Date,
  joursFeries: string[] = [] // tableau de dates 'YYYY-MM-DD'
): number {
  const debut = typeof dateDebut === 'string' ? new Date(dateDebut) : dateDebut;
  const fin = typeof dateFin === 'string' ? new Date(dateFin) : dateFin;
  if (isNaN(debut.getTime()) || isNaN(fin.getTime()) || fin < debut) return 0;
  const feriesSet = new Set(joursFeries);
  let count = 0;
  const cur = new Date(debut);
  while (cur <= fin) {
    const day = cur.getDay(); // 0 = dimanche, 6 = samedi
    const iso = cur.toISOString().slice(0, 10);
    if (day !== 0 && day !== 6 && !feriesSet.has(iso)) count++;
    cur.setDate(cur.getDate() + 1);
  }
  return count;
}

export function calculerDureeContratMois(
  dateDebut: string | Date,
  dateFin: string | Date | null
): number | null {
  if (!dateFin) return null; // CDI : duree indefinie
  const debut = typeof dateDebut === 'string' ? new Date(dateDebut) : dateDebut;
  const fin = typeof dateFin === 'string' ? new Date(dateFin) : dateFin;
  if (isNaN(debut.getTime()) || isNaN(fin.getTime()) || fin < debut) return 0;
  const diffJours = Math.floor((fin.getTime() - debut.getTime()) / (1000 * 60 * 60 * 24));
  return Math.round((diffJours / 30.44) * 100) / 100;
}

export function calculerJoursRestants(
  dateEcheance: string | Date | null,
  dateReference: Date = new Date()
): number | null {
  if (!dateEcheance) return null;
  const cible = typeof dateEcheance === 'string' ? new Date(dateEcheance) : dateEcheance;
  if (isNaN(cible.getTime())) return null;
  const diff = cible.getTime() - dateReference.getTime();
  return Math.ceil(diff / (1000 * 60 * 60 * 24));
}

export function badgeJourRestant(jours: number | null): 'valide' | 'a_renouveler' | 'expire' | 'n_a' {
  if (jours === null) return 'n_a';
  if (jours < 0) return 'expire';
  if (jours <= 30) return 'a_renouveler';
  return 'valide';
}

export function calculerTauxPresence(
  joursPresents: number,
  joursOuvrables: number
): number {
  if (joursOuvrables <= 0) return 0;
  const taux = (joursPresents / joursOuvrables) * 100;
  return Math.round(taux * 100) / 100;
}

export function calculerMontantHeuresSupp(
  heuresSupp: number,
  salaireHoraireBase: number,
  tauxMajoration: number // 100 | 125 | 150
): { montantBrut: number; montantCalcule: number } {
  const montantBrut = Math.round(heuresSupp * salaireHoraireBase * 100) / 100;
  // (1 + taux/100) : pour 125%, on multiplie par 1.25 (= +25% par rapport au brut)
  // NB : spec V2 ecrit '1 + taux_majoration/100' : pour taux=125, facteur = 2.25
  //     mais en pratique paie => le brut est deja a 100% et on ajoute 25% => facteur 1.25
  //     On respecte la formule V2 : montant_brut represente deja le brut de base
  const facteur = 1 + tauxMajoration / 100;
  const montantCalcule = Math.round(montantBrut * facteur * 100) / 100;
  return { montantBrut, montantCalcule };
}

export const HEURES_MENSUELLES_BASE = 173.33; // 40h * 4.33 sem

export function calculerSalaireHoraireBase(
  salaireBrutMensuel: number
): number {
  if (salaireBrutMensuel <= 0) return 0;
  return Math.round((salaireBrutMensuel / HEURES_MENSUELLES_BASE) * 100) / 100;
}

export function calculerMensualitePret(
  montantAccorde: number,
  tauxInteretAnnuel: number,
  dureeMois: number
): number {
  if (dureeMois <= 0) return 0;
  if (tauxInteretAnnuel === 0) {
    return Math.round((montantAccorde / dureeMois) * 100) / 100;
  }
  const r = tauxInteretAnnuel / 100 / 12;
  const mensualite = (montantAccorde * r) / (1 - Math.pow(1 + r, -dureeMois));
  return Math.round(mensualite * 100) / 100;
}

export function calculerSoldeRestantPret(
  montantAccorde: number,
  mensualite: number,
  moisPayes: number
): number {
  if (moisPayes <= 0) return Math.round(montantAccorde * 100) / 100;
  const solde = montantAccorde - (mensualite * moisPayes);
  return Math.round(Math.max(0, solde) * 100) / 100;
}

export const TAUX_CHARGES_DEFAUT = 16.25; // % Cameroon (CNPS + autres)

export function calculerCotisations(
  salaireBrut: number,
  tauxCharges: number = TAUX_CHARGES_DEFAUT
): number {
  return Math.round(salaireBrut * (tauxCharges / 100) * 100) / 100;
}

export function calculerTauxCharges(
  cotisations: number,
  salaireBrut: number
): number {
  if (salaireBrut <= 0) return 0;
  return Math.round((cotisations / salaireBrut) * 10000) / 100;
}

export interface ComputeNetAPayerInput {
  salaireBase: number;
  heuresSuppMontantCalcule?: number;
  primes?: number;
  retenuesAbsences?: number;
  tauxCharges?: number;
  deductionsPrets?: number;
  autresRetenues?: number;
}

export function calculerNetAPayer(input: ComputeNetAPayerInput): {
  salaireBrut: number;
  cotisations: number;
  netAPayer: number;
} {
  const taux = input.tauxCharges ?? TAUX_CHARGES_DEFAUT;
  const salaireBrut =
    input.salaireBase
    + (input.heuresSuppMontantCalcule ?? 0)
    + (input.primes ?? 0)
    - (input.retenuesAbsences ?? 0);
  const cotisations = Math.round(salaireBrut * (taux / 100) * 100) / 100;
  const netAPayer =
    salaireBrut
    - cotisations
    - (input.deductionsPrets ?? 0)
    - (input.autresRetenues ?? 0);
  return {
    salaireBrut: Math.round(salaireBrut * 100) / 100,
    cotisations,
    netAPayer: Math.round(netAPayer * 100) / 100,
  };
}

export type MotifDepart = 'demission' | 'licenciement' | 'fin_cdd' | 'retraite' | 'deces';

export function calculerIndemniteDepart(params: {
  motif: MotifDepart;
  salaireMoyenMensuel: number;
  anneesAnciennete: number;
  sommeSalairesBrutsPeriode?: number;
  indemniteConventionnelleRetraite?: number;
}): number {
  const { motif, salaireMoyenMensuel, anneesAnciennete } = params;
  switch (motif) {
    case 'demission':
      return 0;
    case 'fin_cdd':
      // Prime de precarite 10% sur la somme des salaires bruts de la periode
      return Math.round((params.sommeSalairesBrutsPeriode ?? 0) * 0.10 * 100) / 100;
    case 'licenciement':
      // (1/5 * salaire_moyen * annees) + (2/15 * salaire_moyen * annees > 10)
      const anneesAuDela10 = Math.max(0, anneesAnciennete - 10);
      const indemnite = (salaireMoyenMensuel * anneesAnciennete / 5)
                      + (salaireMoyenMensuel * anneesAuDela10 * 2 / 15);
      return Math.round(indemnite * 100) / 100;
    case 'retraite':
      return Math.round((params.indemniteConventionnelleRetraite ?? 0) * 100) / 100;
    case 'deces':
      // Indemnite equivalente au licenciement verse aux ayants droit
      return calculerIndemniteDepart({ ...params, motif: 'licenciement' });
    default:
      return 0;
  }
}

export function calculerSoldeToutCompte(params: {
  dernierSalaire: number;
  indemniteDepart: number;
  indemniteCongesPayes: number;
  primes: number;
}): number {
  const total = params.dernierSalaire + params.indemniteDepart + params.indemniteCongesPayes + params.primes;
  return Math.round(total * 100) / 100;
}

export function calculerTauxActifs(
  employesActifs: number,
  totalEmployes: number
): number {
  if (totalEmployes <= 0) return 0;
  const taux = (employesActifs / totalEmployes) * 100;
  return Math.round(taux * 100) / 100;
}

export function calculerAnciennete(
  dateEmbauche: string | Date,
  dateReference: Date = new Date()
): { annees: number; mois: number; totalMois: number; label: string } {
  if (!dateEmbauche) return { annees: 0, mois: 0, totalMois: 0, label: '—' };
  const d = typeof dateEmbauche === 'string' ? new Date(dateEmbauche) : dateEmbauche;
  if (isNaN(d.getTime())) return { annees: 0, mois: 0, totalMois: 0, label: '—' };
  let annees = dateReference.getFullYear() - d.getFullYear();
  let mois = dateReference.getMonth() - d.getMonth();
  if (dateReference.getDate() < d.getDate()) mois -= 1;
  if (mois < 0) { annees -= 1; mois += 12; }
  const totalMois = annees * 12 + mois;
  return { annees, mois, totalMois, label: `${annees}a ${mois}m` };
}

export const SEUILS_RAPPEL: Record<string, number> = {
  expiration_document: 30,
  renouvellement_contrat: 30,
  visite_medicale: 15,
  declaration_sociale: 7,
  echeance_periode_essai: 7,
  destruction_archive: 30,
};

export function doitGenererRappel(
  typeRappel: string,
  dateEcheance: string | Date | null,
  dateReference: Date = new Date()
): { rappel: boolean; joursRestants: number | null; urgence: 'basse' | 'moyenne' | 'haute' } {
  if (!dateEcheance) return { rappel: false, joursRestants: null, urgence: 'basse' };
  const seuil = SEUILS_RAPPEL[typeRappel] ?? 30;
  const cible = typeof dateEcheance === 'string' ? new Date(dateEcheance) : dateEcheance;
  if (isNaN(cible.getTime())) return { rappel: false, joursRestants: null, urgence: 'basse' };
  const jours = Math.ceil((cible.getTime() - dateReference.getTime()) / (1000 * 60 * 60 * 24));
  const rappel = jours <= seuil;
  let urgence: 'basse' | 'moyenne' | 'haute' = 'basse';
  if (jours < 0) urgence = 'haute';
  else if (jours <= 7) urgence = 'haute';
  else if (jours <= 15) urgence = 'moyenne';
  return { rappel, joursRestants: jours, urgence };
}

export const JOURS_OUVRABLES_MOIS = 26; // base mensuelle conges payes

export function calculerIndemniteCongesPayesDepart(
  soldeCongesJours: number,
  salaireBrutMensuel: number
): { salaireJournalierMoyen: number; iccp: number } {
  const salaireJournalierMoyen = Math.round((salaireBrutMensuel / JOURS_OUVRABLES_MOIS) * 100) / 100;
  const iccp = Math.round(soldeCongesJours * salaireJournalierMoyen * 100) / 100;
  return { salaireJournalierMoyen, iccp };
}

export interface KPIsD2 {
  totalEmployes: number;
  employesActifs: number;
  contratsEnVigueur: number;
  masseSalariale: number;
  congesEnAttente: number;
  documentsARepouveler: number;
  declarationsEnRetard: number;
  rappelsEnRetard: number;
  pretsEnCours: number;
  soldePretsRestant: number;
  tauxActifs: number;
  parDepartement: Record<string, number>;
  parTypeContrat: Record<string, number>;
  parCategorie: Record<string, number>;
}

export function computeKPIsFromData(data: {
  employees: Array<{ statut: string; salaire_brut: number; departement: string; type_contrat: string; categorie: string }>;
  contrats: Array<{ statut: string }>;
  conges: Array<{ statut: string }>;
  documents: Array<{ statut: string }>;
  declarations: Array<{ statut: string }>;
  rappels: Array<{ statut: string }>;
  prets: Array<{ statut: string; solde_restant: number }>;
}): KPIsD2 {
  const totalEmployes = data.employees.length;
  const employesActifs = data.employees.filter(e => e.statut === 'Actif').length;
  const contratsEnVigueur = data.contrats.filter(c => c.statut === 'En vigueur').length;
  const masseSalariale = data.employees.filter(e => e.statut === 'Actif').reduce((s, e) => s + e.salaire_brut, 0);
  const congesEnAttente = data.conges.filter(c => c.statut === 'en_attente').length;
  const documentsARepouveler = data.documents.filter(d => d.statut === 'A renouveler' || d.statut === 'Expire').length;
  const declarationsEnRetard = data.declarations.filter(d => d.statut === 'en_retard').length;
  const rappelsEnRetard = data.rappels.filter(r => r.statut === 'en_retard').length;
  const pretsActifs = data.prets.filter(p => p.statut === 'en_remboursement');
  const pretsEnCours = pretsActifs.length;
  const soldePretsRestant = pretsActifs.reduce((s, p) => s + p.solde_restant, 0);

  const parDepartement: Record<string, number> = {};
  const parTypeContrat: Record<string, number> = {};
  const parCategorie: Record<string, number> = {};
  data.employees.filter(e => e.statut !== 'Inactif').forEach(e => {
    parDepartement[e.departement] = (parDepartement[e.departement] || 0) + 1;
    parTypeContrat[e.type_contrat] = (parTypeContrat[e.type_contrat] || 0) + 1;
    parCategorie[e.categorie] = (parCategorie[e.categorie] || 0) + 1;
  });

  return {
    totalEmployes,
    employesActifs,
    contratsEnVigueur,
    masseSalariale,
    congesEnAttente,
    documentsARepouveler,
    declarationsEnRetard,
    rappelsEnRetard,
    pretsEnCours,
    soldePretsRestant,
    tauxActifs: totalEmployes > 0 ? Math.round((employesActifs / totalEmployes) * 100) : 0,
    parDepartement,
    parTypeContrat,
    parCategorie,
  };
}

export function calculerTauxRotation(
  nombreDepartsPeriode: number,
  effectifDebut: number,
  effectifFin: number
): { effectifMoyen: number; turnover: number } {
  const effectifMoyen = (effectifDebut + effectifFin) / 2;
  if (effectifMoyen <= 0) return { effectifMoyen: 0, turnover: 0 };
  const turnover = (nombreDepartsPeriode / effectifMoyen) * 100;
  return {
    effectifMoyen: Math.round(effectifMoyen * 100) / 100,
    turnover: Math.round(turnover * 100) / 100,
  };
}

export interface RetentionKPIs {
  tauxRetention3Mois: number;
  tauxRetention6Mois: number;
  turnoverPrecoceEssai: number;
}

export function calculerRetentionPostEmbauche(
  employees: Array<{ id: string; date_embauche: string; statut: string }>,
  dateReference: Date = new Date()
): RetentionKPIs {
  const troisMoisAvant = new Date(dateReference);
  troisMoisAvant.setMonth(troisMoisAvant.getMonth() - 3);
  const sixMoisAvant = new Date(dateReference);
  sixMoisAvant.setMonth(sixMoisAvant.getMonth() - 6);

  const embauches3 = employees.filter(e => new Date(e.date_embauche) >= troisMoisAvant);
  const embauches6 = employees.filter(e => new Date(e.date_embauche) >= sixMoisAvant);
  const retention3 = embauches3.filter(e => e.statut === 'Actif' || e.statut === 'Essai');
  const retention6 = embauches6.filter(e => e.statut === 'Actif' || e.statut === 'Essai');

  // Turnover precoce = employes devenus Inactifs/Suspendus dans les 6 mois suivant leur embauche
  const turnoverPrecoce = employees.filter(e => {
    const dem = new Date(e.date_embauche);
    return dem >= sixMoisAvant && (e.statut === 'Inactif' || e.statut === 'Suspendu');
  }).length;

  return {
    tauxRetention3Mois: embauches3.length > 0
      ? Math.round((retention3.length / embauches3.length) * 10000) / 100
      : 100,
    tauxRetention6Mois: embauches6.length > 0
      ? Math.round((retention6.length / embauches6.length) * 10000) / 100
      : 100,
    turnoverPrecoceEssai: turnoverPrecoce,
  };
}
